CREATE TABLE IF NOT EXISTS review_schedules (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_id BIGINT NOT NULL REFERENCES agents(id), repository TEXT NOT NULL, interval_hours INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, max_daily_runs INTEGER NOT NULL DEFAULT 1, next_at BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'idle');
CREATE TABLE IF NOT EXISTS repository_reviews (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, schedule_id BIGINT NOT NULL REFERENCES review_schedules(id), agent_id BIGINT NOT NULL REFERENCES agents(id), status TEXT NOT NULL, commit_sha TEXT NOT NULL, report_json TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);
ALTER TABLE review_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE repository_reviews ENABLE ROW LEVEL SECURITY;
